SELECT p.status, COUNT(*) AS n, SUM(p.stop_loss <> s.stop_loss) AS stop_changed, SUM(ABS(p.entry_price - s.latest_price)/s.latest_price > 0.003) AS entry_moved_gt_0_3pct, ROUND(AVG((p.exit_price - p.stop_loss)/p.entry_price*100),3) AS avg_exit_vs_stop_pct FROM crypto_ai.paper_position p JOIN crypto_ai.trade_signal s ON s.id = p.signal_id WHERE p.closed_at IS NOT NULL GROUP BY p.status LIMIT 5;